28	static int compare(FILE *fp, char *expect, int ignore_len)
29	{
30	    int ret;
31	    size_t len = strlen(expect);
32	    size_t ret_fp;
33	    char buf[1024] = {0};
34	
35	    ret = fseek(fp, 0, SEEK_SET);
36	    if (!TEST_CHECK(ret == 0)) {
37	        TEST_MSG("fseek failed");
38	        return ret;
39	    }
40	
41	    ret_fp = fread(&buf[0], 1, sizeof(buf), fp);
42	    if (ret_fp == 0) {
43	        if (!TEST_CHECK(feof(fp) == 0)) {
44	            TEST_MSG("fread error.");
45	            return -1;
46	        }
47	    }
48	
49	    if (ignore_len) {
50	        if (!TEST_CHECK(strstr(&buf[0], expect) != NULL)) {
51	            TEST_MSG("compare error. got=%s expect=%s", &buf[0], expect);
52	            return -1;
53	        }
54	
55	    } else {
56	        if (!TEST_CHECK(strlen(buf) == len)) {
57	            TEST_MSG("length error. len=%d got=%s expect=%s", strlen(buf), &buf[0], expect);
58	            return -1;
59	        }
60	        if (!TEST_CHECK(strncmp(expect, &buf[0], len) == 0)) {
61	            TEST_MSG("compare error. got=%s expect=%s", &buf[0], expect);
62	            return -1;
63	        }
64	    }
65	    return 0;
66	}
